  &lt;figcaption&gt;
  &lt;/figcaption&gt;
 &lt;/figure&gt;
 &lt;figure&gt;
  &lt;img alt="" src="https://game.donga.com/media/__sized__/images/2026/3/6/5cfbd04b04824a62-thumbnail-1920x1080-70.jpg"/&gt;
  &lt;figcaption&gt;
  &lt;/figcaption&gt;
 &lt;/figure&gt;
 &lt;figure&gt;
  &lt;img alt="" src="https://game.donga.com/media/__sized__/images/2026/3/6/6784910e81204540-thumbnail-1920x1080-70.jpg"/&gt;
  &lt;figcaption&gt;
  &lt;/figcaption&gt;
 &lt;/figure&gt;
